prog='''def transform(grid):
    h, w = len(grid), len(grid[0])
    def runs(key):
        # maximal runs of lines with a single nonzero color
        out, cur, col = [], [], None
        for k in range(key and w or h):
            line = [r[k] for r in grid] if key else grid[k]
            nz = set(v for v in line if v != 0)
            c = nz.pop() if len(nz) == 1 else None
            if c is not None and c == col:
                cur.append(k)
            else:
                if cur: out.append((col, cur))
                cur, col = ([k], c) if c is not None else ([], None)
        if cur: out.append((col, cur))
        return out
    def build(axis, rs):
        subs = []
        for c, lines in rs:
            if axis == 'r':
                sub = [grid[i] for i in lines]
            else:
                sub = [[r[j] for j in lines] for r in grid]
            solid = all(v != 0 for row in sub for v in row)
            if solid and len(lines) == len(sub) if axis=='r' else True:
                pass
            # separator: every line fully filled with c
            if all(all(v == c for v in row) for row in sub):
                continue
            subs.append([[1 if v != 0 else 0 for v in row] for row in sub])
        return subs
    rs = runs(0)
    cs = runs(1)
    if len(rs) >= 2 and all(c is None for c, _ in rs) is False:
        subs = build('r', rs)
    else:
        subs = build('c', cs)
    if len(subs) < 2:
        subs = build('c', cs) if subs == build('r', rs) else build('r', rs)
    out = subs[0]
    for m in subs[1:]:
        out = [[a & b for a, b in zip(r1, r2)] for r1, r2 in zip(out, m)]
    return [[2 if v else 0 for v in r] for r in out]
'''
